                \${state.activeRefType === 'tag' ? (icons.tag || '') : (icons.branch || '')}
                <span class="ref-btn-label">\${escapeHtml(state.activeRefName || viewCommit?.branch || 'main')}</span>
                <span class="dropdown-caret">▼</span>
