              <span>\${escapeHtml(c.author)}</span>
              <span>committed \${formatDate(c.date)}</span>
            </div>
          </div>
        </div>
        <div class="commit-meta">
          <span class="commit-sha-badge">\${icons.commit} \${escapeHtml(c.shortSha)}</span>
        </div>
