            </thead>
            <tbody>
              \${targetPoints.slice().reverse().map(p => \`
                <tr>
                  <td>
                    <span class="commit-sha-badge">\${icons.commit} \${escapeHtml(p.shortSha)}</span>
                  </td>
                  <td>
                    <span class="rate-badge \${getRateClass(p.linesPct)}">\${p.linesPct}%</span>
