      padding: 6px 14px;
      font-size: 14px;
      font-weight: 500;
      line-height: 20px;
      border-radius: 6px;
      cursor: pointer;
      border: 1px solid var(--color-btn-border);
      background-color: var(--color-btn-bg);
      color: var(--color-fg-default);
      text-decoration: none;
      transition: 0.15s ease-in-out;
    }
    .btn:hover {
      background-color: var(--color-border-muted);
      text-decoration: none;
    }
    .btn-primary {
