      opacity: 0.9;
    }
    .btn-sm {
      padding: 3px 10px;
      font-size: 12px;
      line-height: 18px;
    }

    .container {
      max-width: 1140px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Hero Section */
    .hero {
      padding: 72px 0 48px;
      text-align: center;
      border-bottom: 1px solid var(--color-border-muted);
    }
    .hero-pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 4px 12px;
      margin-bottom: 24px;
      font-size: 12px;
      font-weight: 600;
      color: var(--color-accent-fg);
      background-color: var(--color-canvas-subtle);
      border: 1px solid var(--color-border-default);
