      color: var(--color-fg-muted);
      max-width: 720px;
      margin: 0 auto 32px;
      line-height: 1.6;
    }
    .hero-ctas {
      display: flex;
      justify-content: center;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
      margin-bottom: 48px;
    }

    /* Live Preview Card */
    .preview-card {
      background: var(--color-canvas-subtle);
      border: 1px solid var(--color-border-default);
      border-radius: 8px;
      overflow: hidden;
      box-shadow: 0 10px 30px rgba(0,0,0,0.06);
      text-align: left;
      margin-top: 16px;
