    .preview-card-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px 16px;
      background: var(--color-canvas-default);
      border-bottom: 1px solid var(--color-border-default);
    }
    .preview-title {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 600;
      font-size: 13px;
    }
    .preview-stats-bar {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 16px;
      padding: 20px 24px;
      background-color: var(--color-canvas-default);
      border-bottom: 1px solid var(--color-border-muted);
    }
    .stat-box {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .stat-label {
      font-size: 12px;
      color: var(--color-fg-muted);
      text-transform: uppercase;
      font-weight: 600;
      letter-spacing: 0.5px;
    }
    .stat-value {
      font-size: 24px;
      font-weight: 700;
      color: var(--color-fg-default);
    }
    .stat-progress {
      height: 6px;
      background: var(--color-border-muted);
      border-radius: 3px;
      overflow: hidden;
      margin-top: 4px;
    }
    .stat-fill {
      height: 100%;
      background: var(--color-success-emphasis);
      border-radius: 3px;
    }

    .preview-actions {
      padding: 16px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      background-color: var(--color-canvas-subtle);
      border-top: 1px solid var(--color-border-muted);
    }

    /* Section Headers */
    .section {
      padding: 64px 0;
      border-bottom: 1px solid var(--color-border-muted);
    }
    .section-title {
      font-size: 28px;
      font-weight: 700;
      margin-bottom: 8px;
      text-align: center;
    }
    .section-subtitle {
      font-size: 16px;
      color: var(--color-fg-muted);
      text-align: center;
      margin-bottom: 40px;
      max-width: 680px;
      margin-left: auto;
      margin-right: auto;
    }

    /* Features Grid */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 24px;
    }
    .feature-card {
      padding: 24px;
      background: var(--color-canvas-subtle);
      border: 1px solid var(--color-border-default);
      border-radius: 8px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .feature-title {
      font-size: 16px;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .feature-desc {
      font-size: 14px;
      color: var(--color-fg-muted);
      line-height: 1.5;
    }

    /* Playground / Badges */
    .badge-builder {
      background: var(--color-canvas-subtle);
      border: 1px solid var(--color-border-default);
      border-radius: 8px;
      padding: 32px;
      max-width: 800px;
      margin: 0 auto;
    }
    .form-group {
      margin-bottom: 20px;
    }
    .form-label {
      display: block;
      font-size: 13px;
      font-weight: 600;
      margin-bottom: 6px;
    }
    .form-input, .form-select {
      width: 100%;
      padding: 8px 12px;
      font-size: 14px;
      font-family: var(--font-stack);
      border: 1px solid var(--color-border-default);
      border-radius: 6px;
      background: var(--color-canvas-default);
      color: var(--color-fg-default);
    }
    .badge-preview-box {
      margin-top: 24px;
      padding: 20px;
      background: var(--color-canvas-default);
      border: 1px solid var(--color-border-default);
      border-radius: 6px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      align-items: center;
    }
    .badge-img-wrap {
      padding: 12px;
    }
    .code-preview {
      width: 100%;
      background: var(--color-canvas-subtle);
      border: 1px solid var(--color-border-muted);
      border-radius: 6px;
      padding: 12px;
      font-family: var(--font-mono);
      font-size: 12px;
      overflow-x: auto;
      white-space: pre-wrap;
      word-break: break-all;
    }

    /* Benchmarks Table */
    .benchmarks-table-wrap {
      overflow-x: auto;
      border: 1px solid var(--color-border-default);
      border-radius: 8px;
      padding: 16px;
      background-color: var(--color-canvas-subtle);
    }
    .benchmarks-table {
      width: 100%;
      border-collapse: separate;
      border-spacing: 0;
      background-color: var(--color-canvas-default);
      border: 1px solid var(--color-border-muted);
      border-radius: 6px;
      overflow: hidden;
      text-align: left;
      font-size: 13px;
    }
    .benchmarks-table th, .benchmarks-table td {
      padding: 12px 18px;
      border-bottom: 1px solid var(--color-border-muted);
    }
    .benchmarks-table th {
      background: var(--color-canvas-subtle);
      font-weight: 600;
    }
    .benchmarks-table tr:last-child td {
      border-bottom: none;
    }
    .highlight-cell {
      color: var(--color-success-fg);
      font-weight: 600;
    }

    /* Code Tabs */
    .code-tabs {
      border: 1px solid var(--color-border-default);
      border-radius: 8px;
      overflow: hidden;
      max-width: 800px;
      margin: 0 auto;
    }
    .tabs-header {
      display: flex;
      background: var(--color-canvas-subtle);
      border-bottom: 1px solid var(--color-border-default);
      overflow-x: auto;
    }
    .tab-btn {
      padding: 10px 16px;
      font-size: 13px;
      font-weight: 600;
      color: var(--color-fg-muted);
      background: none;
      border: none;
      cursor: pointer;
      border-bottom: 2px solid transparent;
    }
    .tab-btn.active {
      color: var(--color-fg-default);
      border-bottom-color: var(--color-accent-emphasis);
      background: var(--color-canvas-default);
    }
    .tab-content {
      padding: 20px;
      background: var(--color-canvas-default);
      font-family: var(--font-mono);
      font-size: 13px;
      line-height: 1.6;
      overflow-x: auto;
      white-space: pre;
    }

    /* Toast */
    .toast {
      position: fixed;
      bottom: 24px;
      right: 24px;
      background: #1f2328;
      color: #ffffff;
      padding: 10px 18px;
      border-radius: 6px;
      font-size: 13px;
      font-weight: 500;
      display: none;
      z-index: 1000;
      box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    }
    [data-color-mode="dark"] .toast {
      background: #30363d;
      color: #f0f6fc;
    }

    /* Footer */
    .site-footer {
      padding: 48px 0;
      text-align: center;
      color: var(--color-fg-muted);
      font-size: 13px;
    }
  </style>
</head>
<body>
  <!-- Header -->
